def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, 18.0 if hp > 3 else 45.0))

    desperate = 0
    rich = 0
    prev_bids = []
    prev_high = 0.0
    prev_competitive = 0

    for opp in alive:
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate += 1
        if opp.get('budget', 0) >= 200:
            rich += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            b = float(bid)
            prev_bids.append(b)
            if b > prev_high:
                prev_high = b
            if b >= 90:
                prev_competitive += 1

    low_supply = supply <= 17
    high_supply = supply >= 22

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2
    if no_water >= 1:
        urgency += 3
    if low_supply:
        urgency += 2
    if desperate >= 2:
        urgency += 2
    if prev_high >= 120:
        urgency += 2
    elif prev_high >= 90:
        urgency += 1
    if day >= 8:
        urgency += 1

    if hp >= 7 and no_water == 0 and high_supply and prev_high >= 100:
        return float(min(budget, 8.0))

    if urgency <= 1:
        base = 14.0 if high_supply else 20.0
        if prev_high > 0:
            base = min(base, max(12.0, prev_high * 0.22))
        return float(min(budget, base))

    if urgency == 2:
        base = 26.0 if high_supply else 34.0
        if prev_bids:
            base = max(base, min(48.0, prev_high * 0.38))
        return float(min(budget, base))

    if urgency == 3:
        target = 52.0
        if prev_bids:
            target = max(target, min(78.0, prev_high * 0.62 + 2.0))
        return float(min(budget, target))

    if urgency == 4:
        target = 78.0
        if prev_bids:
            target = max(target, min(108.0, prev_high * 0.82 + 3.0))
        return float(min(budget, target))

    target = 108.0
    if prev_bids:
        target = max(target, min(145.0, prev_high + 4.0))
    if hp <= 1 or no_water >= 2:
        target = max(target, 132.0)
    if rich == 0 and prev_competitive == 0:
        target = min(target, 95.0)

    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    if not alive:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # React to yesterday's immediate pressure: use max bid among alive opponents yesterday.
    prev_bids = []
    for oid, o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            prev_bids.append(float(b))

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how many full water units supply can cover (1 unit == WATER_REQ water).
    # Use int() indices only; here we just compute a float ratio.
    units = supply / float(WATER_REQ) if WATER_REQ > 0 else 0.0

    # Baseline aggressiveness by supply regime.
    if supply >= 21.0:
        base = DAILY_SALARY * 0.65
    elif supply >= 17.0:
        base = DAILY_SALARY * 0.75
    else:
        base = DAILY_SALARY * 0.85

    # If someone previously bid very high, we must overtake to secure water.
    # Cindy averaged ~127 and survived; treat that as a threshold.
    if highest_prev_bid >= DAILY_SALARY * 1.25:
        target = highest_prev_bid + 5.0
    elif highest_prev_bid >= DAILY_SALARY * 0.95:
        target = max(base, highest_prev_bid + 2.0)
    else:
        target = base

    # Urgency adjustments.
    # If we have been dry, increase bid sharply.
    if my_no_water_days >= 2:
        target *= 1.25
    if my_hp <= 2:
        target *= 1.35

    # Budget safety: never bid above what we can afford.
    target = float(target)
    bid = min(my_budget, target)

    # If budget is low, still bid enough to try to prevent further no-water days.
    if bid < DAILY_SALARY * 0.25 and my_hp > 2:
        bid = min(my_budget, DAILY_SALARY * 0.3)

    # Clamp non-negative.
    if bid < 0.0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    bid_amount = DAILY_SALARY * 0.55

    if my_status['hp'] <= 2:
        bid_amount = DAILY_SALARY * 0.99
    elif my_status['hp'] <= 5:
        bid_amount = DAILY_SALARY * 0.85
    else:
        num_full_water_slots = int(day_context['supply'] // WATER_REQ)

        if num_full_water_slots >= num_alive_opponents + 1:
            bid_amount = DAILY_SALARY * 0.3
        elif num_full_water_slots >= 2:
            if highest_prev_bid > DAILY_SALARY * 0.8:
                bid_amount = max(bid_amount, highest_prev_bid + 0.5)
            else:
                bid_amount = DAILY_SALARY * 0.5
        else:
            if highest_prev_bid > DAILY_SALARY * 0.8:
                bid_amount = max(bid_amount, highest_prev_bid + 1.0)
            elif highest_prev_bid > DAILY_SALARY * 0.6:
                bid_amount = max(bid_amount, highest_prev_bid + 0.5)
            else:
                bid_amount = DAILY_SALARY * 0.65

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2:
        if my_status['hp'] <= 5:
            bid_amount = DAILY_SALARY * 0.99
        elif my_status['hp'] >= 8:
            bid_amount = max(bid_amount, DAILY_SALARY * 0.7)

    final_bid = min(my_status['budget'], bid_amount)

    if final_bid <= 0.01 and my_status['budget'] > 0:
        final_bid = 1.0

    return final_bid

def get_bid(day_context, my_status, opponents_status):
